 stage.addEventListener('pointermove',e=>{if(!drag)return;const g=drag;if(g.type==='pan'){planBox=[g.box[0]-(e.clientX-g.start[0])*g.box[2]/g.rect.width,g.box[1]-(e.clientY-g.start[1])*g.box[3]/g.rect.height,g.box[2],g.box[3]];stage.querySelector('svg').setAttribute('viewBox',planBox.join(' '));}else if(g.type==='contour'){const point=svgPoint(e);correctProfile(g.source,g.index,point.x-g.start.x,g.start.y-point.y);}else{const point=svgPoint(e),delta=g.key==='temporalLift'?g.start.y-point.y:point.x-g.start.x,max={nasalAngle:15,temporalLift:12,temporalReach:8}[g.key];change(g.key,Math.round(clamp(g.value+delta*(g.key==='nasalAngle'?.8:1),0,max)*10)/10);}});
